# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">1. ÜNİTE GENEL DEĞERLENDİRMESİ: DİNİMİZ İSLAM VE MÜMİN KİMLİĞİ</text>\n  <rect x="25" y="55" width="205" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="127" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İslam\'ın Temel Yapısı</text>\n  <text x="127" y="108" text-anchor="middle" font-size="11" fill="#1e3a8a">• Tevhid: Allah\'ın birliği ve</text>\n  <text x="127" y="124" text-anchor="middle" font-size="11" fill="#1e3a8a">eşsizliği (Kelime-i Tevhid).</text>\n  <text x="127" y="148" text-anchor="middle" font-size="11" fill="#1e3a8a">• İman (İnanç) Esasları: 6 esas.</text>\n  <text x="127" y="172" text-anchor="middle" font-size="11" fill="#1e3a8a">• İslam\'ın Şartları: 5 temel ibadet.</text>\n  <text x="127" y="196" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">• İman - İbadet - Ahlak Bütünlüğü</text>\n  <rect x="247" y="55" width="205" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Esmâ-i Hüsnâ Bilinci</text>\n  <text x="350" y="108" text-anchor="middle" font-size="11" fill="#14532d">• El-Hâdî: Doğru yolu (hidayeti)</text>\n  <text x="350" y="124" text-anchor="middle" font-size="11" fill="#14532d">gösteren, rehberlik eden.</text>\n  <text x="350" y="148" text-anchor="middle" font-size="11" fill="#14532d">• Es-Selâm: Esenlik, barış ve</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11" fill="#14532d">güven veren, kusursuz olan.</text>\n  <text x="350" y="188" text-anchor="middle" font-size="11" fill="#14532d">• El-Vekîl: Tedbir alıp tevekkül</text>\n  <text x="350" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">edenlerin işini en güzel yöneten.</text>\n  <rect x="470" y="55" width="205" height="180" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="572" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">İslam\'ın Evrensel İlkeleri</text>\n  <text x="572" y="108" text-anchor="middle" font-size="11" fill="#713f12">• Fıtrat Dini: İnsanın yaratılış</text>\n  <text x="572" y="124" text-anchor="middle" font-size="11" fill="#713f12">özellikleriyle tam uyumludur.</text>\n  <text x="572" y="148" text-anchor="middle" font-size="11" fill="#713f12">• Kolaylık Dini: Güç yetiremeyecek</text>\n  <text x="572" y="164" text-anchor="middle" font-size="11" fill="#713f12">yükümlülük yüklemez.</text>\n  <text x="572" y="188" text-anchor="middle" font-size="11" fill="#713f12">• Denge (İtidal): Dünya ve</text>\n  <text x="572" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">ahiret mutluluğunu birleştirir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. ÜNİTEYE GİRİŞ: İSLAM\'DA TEMİZLİK (TAHÂRET) BOYUTLARI</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#0e7490">1. Maddi (Bedensel ve Çevresel) Temizlik</text>\n  <text x="180" y="108" text-anchor="middle" font-size="11" fill="#164e63">• Hadesten Tahâret: Abdest, gusül ve teyemmüm</text>\n  <text x="180" y="124" text-anchor="middle" font-size="11" fill="#164e63">ile hükmi kirlilikten arınmak.</text>\n  <text x="180" y="148" text-anchor="middle" font-size="11" fill="#164e63">• Necâsetten Tahâret: Beden, elbise ve ibadet</text>\n  <text x="180" y="164" text-anchor="middle" font-size="11" fill="#164e63">edilecek yeri gözle görülür kirden temizlemek.</text>\n  <text x="180" y="190" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">• Çevre Temizliği: Suları, sokakları ve</text>\n  <text x="180" y="206" text-anchor="middle" font-size="11" fill="#164e63">ortak yaşam alanlarını temiz tutmak.</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="520" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#be185d">2. Manevi (Kalp ve Ahlak) Temizliği</text>\n  <text x="520" y="108" text-anchor="middle" font-size="11" fill="#831843">• Kalbi şirkten, ikiyüzlülükten (riya),</text>\n  <text x="520" y="124" text-anchor="middle" font-size="11" fill="#831843">kibirden, kinden ve hasetten arındırmak.</text>\n  <text x="520" y="148" text-anchor="middle" font-size="11" fill="#831843">• Dili yalandan, gıybetten ve kırıcı sözden;</text>\n  <text x="520" y="164" text-anchor="middle" font-size="11" fill="#831843">kazancı ise haram ve hileden uzak tutmak.</text>\n  <text x="520" y="190" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">• Günahlardan Tövbe ve İstiğfar ile temizlenmek.</text>\n  <text x="520" y="210" text-anchor="middle" font-size="11" fill="#475569">«Temizlik imanın yarısıdır.» (Hadis-i Şerif)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAM\'DA İBADET BİLİNCİ VE İHLAS İLKESİ (TDB.1.2)</text>\n  <rect x="25" y="55" width="205" height="180" rx="8" fill="#f3e8ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="127" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">İbadetin Anlamı ve Amacı</text>\n  <text x="127" y="108" text-anchor="middle" font-size="11" fill="#581c87">• Allah\'a saygı, sevgi ve</text>\n  <text x="127" y="124" text-anchor="middle" font-size="11" fill="#581c87">itaatle kulluk etmektir.</text>\n  <text x="127" y="150" text-anchor="middle" font-size="11" fill="#581c87">• Verdiği sayısız nimetlere</text>\n  <text x="127" y="166" text-anchor="middle" font-size="11" font-weight="bold" fill="#6d28d9">şükretmenin en güzel yoludur.</text>\n  <text x="127" y="196" text-anchor="middle" font-size="11" fill="#475569">Zâriyât Suresi, 56. Ayet</text>\n  <rect x="247" y="55" width="205" height="180" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Kabul Şartları</text>\n  <text x="350" y="108" text-anchor="middle" font-size="11" fill="#7c2d12">1. İman: Sağlam inanç temeli.</text>\n  <text x="350" y="136" text-anchor="middle" font-size="11" font-weight="bold" fill="#9a3412">2. İhlas (Samimiyet):</text>\n  <text x="350" y="152" text-anchor="middle" font-size="11" fill="#7c2d12">Gösterişten (riyadan) uzak,</text>\n  <text x="350" y="168" text-anchor="middle" font-size="11" fill="#7c2d12">Allah rızasını gözetmek.</text>\n  <text x="350" y="196" text-anchor="middle" font-size="11" fill="#7c2d12">3. Sünnete Uygunluk: Hz.</text>\n  <text x="350" y="212" text-anchor="middle" font-size="11" fill="#7c2d12">Peygamber\'in öğrettiği gibi.</text>\n  <rect x="470" y="55" width="205" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="572" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Geniş Anlamda İbadet</text>\n  <text x="572" y="108" text-anchor="middle" font-size="11" fill="#14532d">• Namaz, oruç, zekât, hac</text>\n  <text x="572" y="124" text-anchor="middle" font-size="11" fill="#14532d">özel ibadetlerdir.</text>\n  <text x="572" y="150" text-anchor="middle" font-size="11" fill="#14532d">• Allah rızası için ilim öğrenmek,</text>\n  <text x="572" y="166" text-anchor="middle" font-size="11" fill="#14532d">ailenin rızkını kazanmak ve</text>\n  <text x="572" y="182" text-anchor="middle" font-size="11" fill="#14532d">canlılara merhamet etmek de</text>\n  <text x="572" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">salih amel ve ibadettir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
